static double sumOfAnyNumberList(List<? extends Number> list) {
    double total = 0;
    for (Number n : list) {
        total += n.doubleValue(); // odczyt jako Number - zawsze bezpieczny
    }
    // list.add(5); // BLAD KOMPILACJI
    return total;
}

